\label{tab:logprob_ties}
\begin{tabular}{lc}
\toprule
$\varepsilon$ threshold & Tied instances (\%) \\
\midrule
0.01 & 1.1\% \\
0.05 & 60.3\% \\
0.1  & ${\sim}$84\% \\
0.5  & ${\sim}$99\% \\
\bottomrule
\end{tabular}

